export const code = async (inputs) => {
  const tallyData = inputs.tally_data || {};
  const itemGroups = tallyData.itemGroups || [];
  const now = new Date().toISOString().replace('T', ' ').substring(0, 19);

  const rows = itemGroups.map((item, index) => {
    const groupID = `IGRP-${String(index + 1).padStart(4, '0')}`;
    return [
      groupID,
      'COMP-0001',
      item.itemGroupName || '',
      item.categoryId || '',
      now,
      now,
      1
    ];
  });

  return { rows, count: rows.length };
};

export const code = async (inputs) => {
  const tallyData = inputs.tally_data || {};
  const existingRows = inputs.existing_items || [];
  const items = tallyData.items || [];
  const companyId = 'COMP-0001';
  const now = new Date().toISOString().replace('T', ' ').substring(0, 19);

  // Column indices in Items sheet (0-based, A=0, B=1, ...)
  const COL = {
    ID: 0,              // A: ItemID
    Brand: 3,           // D: Brand
    SubCategory: 5,     // F: SubCategory
    GroupID: 6,         // G: GroupID
    MRP: 11,            // L: MRP
    MinStockLevel: 12,  // M: MinStockLevel
    MaxStockLevel: 13,  // N: MaxStockLevel
    Location: 15,       // P: Location
    CreatedDate: 19,    // T: CreatedDate
    IsBatchTracked: 21  // V: IsBatchTracked
  };

  const getVal = (row, idx) => row && row[idx] !== undefined ? row[idx] : '';

  // Build lookup map by ItemID
  const existingMap = {};
  existingRows.forEach(row => {
    const id = getVal(row, COL.ID);
    if (id) {
      existingMap[id] = {
        Brand: getVal(row, COL.Brand),
        SubCategory: getVal(row, COL.SubCategory),
        GroupID: getVal(row, COL.GroupID),
        MRP: getVal(row, COL.MRP),
        MinStockLevel: getVal(row, COL.MinStockLevel),
        MaxStockLevel: getVal(row, COL.MaxStockLevel),
        Location: getVal(row, COL.Location),
        CreatedDate: getVal(row, COL.CreatedDate),
        IsBatchTracked: getVal(row, COL.IsBatchTracked)
      };
    }
  });

  const rows = items.map((item, index) => {
    // Generate composite ItemID matching seed data format
    const itemID = `ITM-${String(index + 1).padStart(4, '0')}_${companyId}`;
    const existing = existingMap[itemID] || {};

    // Preserve existing values for manually-added columns
    // If new item (no existing row), leave blanks for user to fill
    const brand = existing.Brand || '';
    const subCategory = existing.SubCategory || '';
    const groupID = existing.GroupID || '';
    const mrp = existing.MRP || '';
    const minStockLevel = existing.MinStockLevel || '';
    const maxStockLevel = existing.MaxStockLevel || '';
    const location = existing.Location || '';
    const isBatchTracked = existing.IsBatchTracked || 'FALSE';

    // CreatedDate: preserve existing, only set for new items
    const createdDate = existing.CreatedDate || now;

    return [
      itemID,                                    // 1. A: ItemID (composite)
      companyId,                                 // 2. B: CompanyID
      item.itemName || '',                       // 3. C: ItemName
      brand,                                     // 4. D: Brand (preserve)
      item.categoryId || '',                     // 5. E: CategoryID
      subCategory,                               // 6. F: SubCategory (preserve)
      groupID,                                   // 7. G: GroupID (preserve)
      item.unit || '',                           // 8. H: Unit
      item.openingStock || 0,                    // 9. I: OpeningStock
      item.saleRate || 0,                        // 10. J: SaleRate
      item.purchaseRate || 0,                    // 11. K: PurchaseRate
      mrp,                                       // 12. L: MRP (preserve)
      minStockLevel,                             // 13. M: MinStockLevel (preserve)
      maxStockLevel,                             // 14. N: MaxStockLevel (preserve)
      item.reorderLevel || 0,                    // 15. O: ReorderLevel
      location,                                  // 16. P: Location (preserve)
      item.hsnCode || '',                        // 17. Q: HSN
      item.gstRate || 0,                         // 18. R: GST
      item.isActive ? 'TRUE' : 'FALSE',         // 19. S: IsActive (FIXED)
      createdDate,                               // 20. T: CreatedDate (preserve)
      now,                                       // 21. U: LastModifiedDate (always now)
      isBatchTracked                            // 22. V: IsBatchTracked (preserve)
    ];
  });

  return { rows, count: rows.length };
};
